export default function window() {
  const now = Date.now(),
    start = now + 86400000,
    end = now + 7 * 86400000;
  return {
    timeMin: new Date(now).toISOString(),
    timeMax: new Date(end).toISOString(),
    start: new Date(start).toISOString(),
    end: new Date(end).toISOString(),
  };
}

