export default function pages({ previous, items, token }) {
  let s = previous ?? { started: false, events: [], seen: [] };
  if (!s.started) return { state: { ...s, started: true }, more: true, pageToken: "", events: [] };
  if (!Array.isArray(items)) throw Error("Missing calendar event page");
  const all = [...s.events, ...items];
  if (all.length > 5000) throw Error("Too many events");
  if (token) {
    if (s.seen.includes(token)) throw Error("Repeated page token");
    return {
      state: { started: true, events: all, seen: [...s.seen, token] },
      more: true,
      pageToken: token,
      events: all,
    };
  }
  return {
    state: { started: true, events: all, seen: s.seen },
    more: false,
    pageToken: "",
    events: all,
  };
}

