export default function slots({ start, end, events }) {
  const from = Date.parse(start),
    until = Date.parse(end);
  if (!Number.isFinite(from) || !Number.isFinite(until) || until <= from)
    throw Error("Invalid time window");
  const busy = events
    .filter((e) => e?.start?.dateTime && e?.end?.dateTime)
    .map((e) => [Date.parse(e.start.dateTime), Date.parse(e.end.dateTime)]);
  if (busy.some(([a, b]) => !Number.isFinite(a) || !Number.isFinite(b) || b <= a))
    throw Error("Invalid event time");
  const allday = events
    .filter((e) => e?.start?.date && e?.end?.date)
    .map((e) => [e.start.date, e.end.date]);
  const fmt = new Intl.DateTimeFormat("en-US", {
      timeZone: "America/New_York",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      weekday: "short",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
      timeZoneName: "shortOffset",
    }),
    parts = (t) =>
      Object.fromEntries(
        fmt
          .formatToParts(new Date(t))
          .filter((x) => x.type !== "literal")
          .map((x) => [x.type, x.value]),
      ),
    format = (t) => {
      let p = parts(t),
        z = p.timeZoneName.match(/^GMT([+-])(\d{1,2})(?::(\d\d))?$/);
      if (!z) throw Error("Cannot determine Eastern offset");
      return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}${z[1]}${z[2].padStart(2, "0")}:${z[3] ?? "00"}`;
    };
  let available = [];
  for (let t = (Math.floor(from / 1800000) + 1) * 1800000; t + 1800000 <= until; t += 1800000) {
    const p = parts(t),
      hour = Number(p.hour);
    if (
      ["Sat", "Sun"].includes(p.weekday) ||
      hour < 9 ||
      hour >= 17 ||
      allday.some(
        ([a, b]) => `${p.year}-${p.month}-${p.day}` >= a && `${p.year}-${p.month}-${p.day}` < b,
      ) ||
      busy.some(([a, b]) => t < b && t + 1800000 > a)
    )
      continue;
    available.push(format(t) + " - " + format(t + 1800000));
  }
  return { availableSlots: available.join(", "), slots: available };
}
